"""M1 data model: tenancy, identity, RBAC, sessions and audit.

Design rules (see ARCHITECTURE.md):
* UUID primary keys generated by PostgreSQL (gen_random_uuid()).
* Every tenant-scoped table carries ``organization_id``.
* Timestamps are stored in UTC (timestamptz).
* ``audit_events`` is append-only (enforced by database trigger).
* Users are global identities; tenancy is established by memberships.
"""
from __future__ import annotations

import uuid
from datetime import date, datetime

from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    Date,
    DateTime,
    Integer,
    ForeignKey,
    Index,
    PrimaryKeyConstraint,
    String,
    Text,
    UniqueConstraint,
    text,
)
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column

from .db import Base

UUID_PK = uuid.UUID


def _uuid_default() -> "text":
    return text("gen_random_uuid()")


def _now() -> "text":
    return text("now()")


now = _now


class Organization(Base):
    __tablename__ = "organizations"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    name: Mapped[str] = mapped_column(String(200), nullable=False)
    slug: Mapped[str] = mapped_column(String(80), nullable=False, unique=True)
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="active",
        server_default="active",
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        CheckConstraint("status IN ('active','suspended','deleting')", name="ck_org_status"),
    )


class Branch(Base):
    __tablename__ = "branches"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=False,
    )
    name: Mapped[str] = mapped_column(String(200), nullable=False)
    code: Mapped[str] = mapped_column(String(30), nullable=False)
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="active", server_default="active"
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        UniqueConstraint("organization_id", "code", name="uq_branch_org_code"),
        Index("ix_branches_org_created", "organization_id", "created_at"),
        CheckConstraint("status IN ('active','inactive')", name="ck_branch_status"),
    )


class User(Base):
    """Global identity. Never exposed to other tenants; password_hash is
    excluded from every API schema."""

    __tablename__ = "users"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    email: Mapped[str] = mapped_column(String(320), nullable=False, unique=True)
    full_name: Mapped[str] = mapped_column(String(200), nullable=False)
    password_hash: Mapped[str] = mapped_column(String(255), nullable=False)
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="active", server_default="active"
    )
    is_superadmin: Mapped[bool] = mapped_column(
        Boolean, nullable=False, default=False, server_default=text("false")
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        CheckConstraint("status IN ('active','disabled')", name="ck_user_status"),
    )


class Role(Base):
    __tablename__ = "roles"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    key: Mapped[str] = mapped_column(String(40), nullable=False, unique=True)
    name: Mapped[str] = mapped_column(String(100), nullable=False)
    description: Mapped[str] = mapped_column(Text, nullable=False, default="", server_default="")
    system: Mapped[bool] = mapped_column(
        Boolean, nullable=False, default=True, server_default=text("true")
    )


class Permission(Base):
    """Permission catalogue. Keys are stable strings checked in code."""

    __tablename__ = "permissions"

    key: Mapped[str] = mapped_column(String(60), primary_key=True)
    description: Mapped[str] = mapped_column(Text, nullable=False, default="", server_default="")


class RolePermission(Base):
    __tablename__ = "role_permissions"

    role_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("roles.id", ondelete="CASCADE"), primary_key=True
    )
    permission_key: Mapped[str] = mapped_column(
        String(60), ForeignKey("permissions.key", ondelete="CASCADE"), primary_key=True
    )


class Membership(Base):
    """Links a global user to a tenant (and optionally a branch) with a role."""

    __tablename__ = "memberships"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    user_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE"), nullable=False
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False
    )
    branch_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("branches.id", ondelete="SET NULL"), nullable=True
    )
    role_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("roles.id", ondelete="RESTRICT"), nullable=False
    )
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="active", server_default="active"
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        UniqueConstraint("user_id", "organization_id", name="uq_membership_user_org"),
        Index("ix_memberships_org", "organization_id"),
        CheckConstraint("status IN ('active','suspended')", name="ck_membership_status"),
    )


class RefreshSession(Base):
    """Server-side session backing both refresh and (via ``sid``) access tokens.

    Refresh tokens are opaque; only their SHA-256 hash is stored.
    Rotation families enable reuse detection: replaying a rotated token
    revokes the whole family.
    """

    __tablename__ = "auth_sessions"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    family_id: Mapped[UUID_PK] = mapped_column(UUID(as_uuid=True), nullable=False, index=True)
    user_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE"), nullable=False
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False
    )
    token_hash: Mapped[str] = mapped_column(String(64), nullable=False, unique=True)
    issued_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    replaced_by: Mapped[UUID_PK | None] = mapped_column(UUID(as_uuid=True), nullable=True)
    user_agent: Mapped[str | None] = mapped_column(String(400), nullable=True)
    ip_address: Mapped[str | None] = mapped_column(String(60), nullable=True)

    __table_args__ = (
        Index("ix_auth_sessions_user_org", "user_id", "organization_id"),
    )


class AuditEvent(Base):
    """Tamper-evident, append-only audit trail (UPDATE/DELETE blocked by trigger)."""

    __tablename__ = "audit_events"

    id: Mapped[int] = mapped_column(
        BigInteger, primary_key=True, autoincrement=True
    )
    organization_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("organizations.id", ondelete="SET NULL"), nullable=True
    )
    actor_user_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    action: Mapped[str] = mapped_column(String(80), nullable=False)
    resource_type: Mapped[str | None] = mapped_column(String(60), nullable=True)
    resource_id: Mapped[str | None] = mapped_column(String(80), nullable=True)
    event_metadata: Mapped[dict] = mapped_column(
        "metadata", JSONB, nullable=False, default=dict, server_default=text("'{}'::jsonb")
    )
    correlation_id: Mapped[str | None] = mapped_column(String(64), nullable=True)
    ip_address: Mapped[str | None] = mapped_column(String(60), nullable=True)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        Index("ix_audit_org_created", "organization_id", "created_at"),
        Index("ix_audit_action", "action"),
        PrimaryKeyConstraint("id"),
    )


# --- M2: patients, appointments, OPD queue --------------------------------
# Tenant rules identical to M1: organization_id + strict RLS policies
# (migration 0005). UHID is unique per organization, never globally.


class Patient(Base):
    __tablename__ = "patients"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=False,
    )
    uhid: Mapped[str] = mapped_column(String(20), nullable=False)
    full_name: Mapped[str] = mapped_column(String(200), nullable=False)
    gender: Mapped[str] = mapped_column(String(20), nullable=False)
    date_of_birth: Mapped[date | None] = mapped_column(Date, nullable=True)
    dob_estimated: Mapped[bool] = mapped_column(
        Boolean, nullable=False, default=False, server_default=text("false")
    )
    phone: Mapped[str | None] = mapped_column(String(20), nullable=True)
    address: Mapped[str] = mapped_column(Text, nullable=False, default="")
    blood_group: Mapped[str | None] = mapped_column(String(5), nullable=True)
    allergies: Mapped[str] = mapped_column(Text, nullable=False, default="")
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="active", server_default="active"
    )
    merged_into_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("patients.id", ondelete="SET NULL"), nullable=True
    )
    created_by: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        UniqueConstraint("organization_id", "uhid", name="uq_patient_org_uhid"),
        Index("ix_patients_org_created", "organization_id", "created_at"),
        Index("ix_patients_org_phone", "organization_id", "phone"),
        CheckConstraint(
            "gender IN ('male','female','other','unknown')", name="ck_patient_gender"
        ),
        CheckConstraint(
            "status IN ('active','inactive','merged')", name="ck_patient_status"
        ),
    )


class Appointment(Base):
    __tablename__ = "appointments"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=False,
    )
    branch_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("branches.id", ondelete="RESTRICT"),
        nullable=False,
    )
    patient_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("patients.id", ondelete="RESTRICT"),
        nullable=False,
    )
    provider_user_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    starts_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False
    )
    ends_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    reason: Mapped[str] = mapped_column(String(300), nullable=False, default="")
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="scheduled", server_default="scheduled"
    )
    notes: Mapped[str] = mapped_column(Text, nullable=False, default="")
    created_by: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        CheckConstraint("ends_at > starts_at", name="ck_appt_end_after_start"),
        CheckConstraint(
            "status IN ('scheduled','checked_in','completed','cancelled','no_show')",
            name="ck_appt_status",
        ),
        Index("ix_appt_org_starts", "organization_id", "starts_at"),
        Index("ix_appt_org_patient", "organization_id", "patient_id"),
    )


class OpdQueueEntry(Base):
    __tablename__ = "opd_queue"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=False,
    )
    branch_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("branches.id", ondelete="RESTRICT"),
        nullable=False,
    )
    patient_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("patients.id", ondelete="RESTRICT"),
        nullable=False,
    )
    appointment_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("appointments.id", ondelete="SET NULL"),
        nullable=True,
    )
    service_date: Mapped[date] = mapped_column(Date, nullable=False)
    token_number: Mapped[int] = mapped_column(Integer, nullable=False)
    status: Mapped[str] = mapped_column(
        String(20), nullable=False, default="waiting", server_default="waiting"
    )
    priority: Mapped[str] = mapped_column(
        String(20), nullable=False, default="normal", server_default="normal"
    )
    doctor_user_id: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    called_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    started_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    completed_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    created_by: Mapped[UUID_PK | None] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="SET NULL"), nullable=True
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        UniqueConstraint(
            "organization_id", "service_date", "token_number",
            name="uq_queue_org_date_token",
        ),
        CheckConstraint(
            "status IN ('waiting','called','in_consultation','completed','skipped','cancelled')",
            name="ck_queue_status",
        ),
        CheckConstraint("priority IN ('normal','urgent')", name="ck_queue_priority"),
        Index("ix_queue_org_date", "organization_id", "service_date"),
        Index("ix_queue_org_status", "organization_id", "status"),
    )


class IdempotencyKey(Base):
    """Stored responses for retried POSTs (registration desks and the M4
    offline sync client re-send requests; a retry must not duplicate
    patients, appointments or queue entries)."""

    __tablename__ = "idempotency_keys"

    id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    organization_id: Mapped[UUID_PK] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("organizations.id", ondelete="CASCADE"),
        nullable=False,
    )
    idempotency_key: Mapped[str] = mapped_column(String(100), nullable=False)
    endpoint: Mapped[str] = mapped_column(String(120), nullable=False)
    request_hash: Mapped[str] = mapped_column(String(64), nullable=False)
    response_status: Mapped[int] = mapped_column(Integer, nullable=False)
    response_body: Mapped[dict] = mapped_column(JSONB, nullable=False)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=now()
    )

    __table_args__ = (
        UniqueConstraint("organization_id", "idempotency_key", name="uq_idem_org_key"),
        Index("ix_idem_org_created", "organization_id", "created_at"),
    )
